import os
from pathlib import Path
import pandas as pd
import docx


def _read_text_file(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def _extract_docx_text(path: Path) -> str:
    document = docx.Document(str(path))
    parts = []

    for paragraph in document.paragraphs:
        text = paragraph.text.strip()
        if text:
            parts.append(text)

    for table in document.tables:
        table_lines = []
        for row in table.rows:
            cell_texts = [cell.text.strip() for cell in row.cells]
            table_lines.append("\t".join(cell_texts))
        if table_lines:
            parts.append("\n".join(table_lines))

    return "\n".join(parts)


def _extract_xlsx_text(path: Path) -> str:
    parts = []
    excel_file = pd.ExcelFile(path)

    for sheet_name in excel_file.sheet_names:
        df = excel_file.parse(sheet_name=sheet_name, dtype=str)
        df = df.fillna("")
        sheet_text = df.to_csv(index=False)
        if sheet_text.strip():
            parts.append(f"[Sheet: {sheet_name}]\n{sheet_text}")
        else:
            parts.append(f"[Sheet: {sheet_name}]")

    return "\n\n".join(parts)


def _write_csv_with_text(output_path: Path, text: str) -> None:
    pd.DataFrame({"Text": [text]}).to_csv(output_path, index=False)


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    if not source_path.exists() or not source_path.is_dir():
        raise FileNotFoundError(source_directory)

    target_path = Path(target_directory)
    target_path.mkdir(parents=True, exist_ok=True)

    supported_extensions = {".txt", ".docx", ".xlsx", ".csv"}
    converted_count = 0

    for file_path in sorted(source_path.iterdir(), key=lambda p: p.name.lower()):
        if not file_path.is_file():
            continue

        extension = file_path.suffix.lower()
        if extension not in supported_extensions:
            continue

        output_path = target_path / f"{file_path.stem}.csv"

        try:
            if extension == ".txt" or extension == ".csv":
                text = _read_text_file(file_path)
            elif extension == ".docx":
                text = _extract_docx_text(file_path)
            elif extension == ".xlsx":
                text = _extract_xlsx_text(file_path)
            else:
                continue

            _write_csv_with_text(output_path, text)
            converted_count += 1
        except Exception:
            continue

    return converted_count
